// O(n) memory: a set of visited nodes
public bool HasCycleSet(ListNode head) {
    var seen = new HashSet<ListNode>();     // compared by reference
    for (var n = head; n != null; n = n.next)
        if (!seen.Add(n)) return true;      // seen this node before — a cycle
    return false;
}

