public ListNode DetectCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) {                 // phase 1: met, k is a multiple of λ
            var p = head;
            while (p != slow) {             // phase 2: μ steps from both sides
                p = p.next;
                slow = slow.next;
            }
            return p;                       // the cycle entry
        }
    }
    return null;                            // no cycle
}

