// #287: n + 1 numbers from 1 to n, do not modify the array, O(1) memory
public int FindDuplicate(int[] nums) {
    int slow = 0, fast = 0;
    do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast);
    int p = 0;
    while (p != slow) { p = nums[p]; slow = nums[slow]; }
    return p;                     // several arrows lead into the repeat — the cycle entry
}
